    // Tabulated (iterative) Fibonacci in JavaScript
function fib(n) {

    let f = new Array(n + 1);
    f[0] = 0;
    if (n > 0) f[1] = 1;

    for (let i = 2; i <= n; i++) {
        f[i] = f[i - 1] + f[i - 2];
    }

    return f[n];
}

